#pragma once
#define BATTERIES_ASYNC_WRITE_HPP

#include <batteries/config.hpp>
//
#if BATT_CPP_20

#include <batteries/async/io_result.hpp>
#include <batteries/async/task.hpp>
#include <batteries/async/transfer.hpp>

#include <batteries/buffer.hpp>
#include <batteries/int_types.hpp>
#include <batteries/slice.hpp>
#include <batteries/small_vec.hpp>
#include <batteries/status.hpp>

#include <iterator>

namespace batt {

//=#=#==#==#===============+=+=+=+=++=++++++++++++++-++-+--+-+----+---------------
//
template <typename T>
concept ConstBufferSequence = requires(const T& x) {
    // T is copy-constructible from x
    //
    T(x);

    { boost::asio::buffer_sequence_begin(x) } -> std::bidirectional_iterator;
    { boost::asio::buffer_sequence_end(x) } -> std::bidirectional_iterator;
    { *boost::asio::buffer_sequence_begin(x) } -> std::convertible_to<ConstBuffer>;
    { *boost::asio::buffer_sequence_end(x) } -> std::convertible_to<ConstBuffer>;
};

static_assert(ConstBufferSequence<ConstBuffer>);
static_assert(ConstBufferSequence<Slice<ConstBuffer>>);
static_assert(ConstBufferSequence<SmallVec<ConstBuffer, 1>>);

//=#=#==#==#===============+=+=+=+=++=++++++++++++++-++-+--+-+----+---------------
//
struct AsyncWriteSomeOp {
    using SingleBuffer = ConstBuffer;

    template <typename StreamT, typename BuffersT, typename HandlerT>
    static BATT_ALWAYS_INLINE void async_transfer_some_at(StreamT&& stream, u64 /*offset*/,
                                                          BuffersT&& buffers, HandlerT&& handler)
    {
        BATT_FORWARD(stream).async_write_some(BATT_FORWARD(buffers), BATT_FORWARD(handler));
    }
};

//=#=#==#==#===============+=+=+=+=++=++++++++++++++-++-+--+-+----+---------------
//
struct AsyncWriteSomeAtOp {
    using SingleBuffer = ConstBuffer;

    template <typename StreamT, typename BuffersT, typename HandlerT>
    static BATT_ALWAYS_INLINE void async_transfer_some_at(StreamT&& stream, u64 offset, BuffersT&& buffers,
                                                          HandlerT&& handler)
    {
        BATT_FORWARD(stream).async_write_some_at(offset, BATT_FORWARD(buffers), BATT_FORWARD(handler));
    }
};

//==#==========+==+=+=++=+++++++++++-+-+--+----- --- -- -  -  -   -
//
template <typename AsyncStream, ConstBufferSequence BuffersT>
StatusOr<usize> await_write_some(AsyncStream& stream, const BuffersT& buffers) noexcept
{
    IOResult<usize> result = Task::await<IOResult<usize>>([&](auto&& handler) {
        stream.async_write_some(buffers, BATT_FORWARD(handler));
    });
    BATT_REQUIRE_OK(result);
    return *result;
}

//==#==========+==+=+=++=+++++++++++-+-+--+----- --- -- -  -  -   -
//
template <typename AsyncStream, ConstBufferSequence BuffersT>
StatusOr<usize> await_write_some_at(AsyncStream& stream, u64 offset, const BuffersT& buffers) noexcept
{
    IOResult<usize> result = Task::await<IOResult<usize>>([&](auto&& handler) {
        stream.async_write_some_at(offset, buffers, BATT_FORWARD(handler));
    });
    BATT_REQUIRE_OK(result);
    return *result;
}

//==#==========+==+=+=++=+++++++++++-+-+--+----- --- -- -  -  -   -
//
template <typename AsyncStream, ConstBufferSequence BuffersT>
Status await_write_all(AsyncStream& stream, const BuffersT& buffers) noexcept
{
    return await_transfer_all_impl<AsyncWriteSomeOp>(stream, /*offset=*/0, buffers);
}

//==#==========+==+=+=++=+++++++++++-+-+--+----- --- -- -  -  -   -
//
template <typename AsyncStream, ConstBufferSequence BuffersT>
Status await_write_all_at(AsyncStream& stream, u64 offset, const BuffersT& buffers) noexcept
{
    return await_transfer_all_impl<AsyncWriteSomeAtOp>(stream, offset, buffers);
}

}  // namespace batt

#endif  // BATT_CPP_20
